1	package br.com.loja.checkout;
2	
3	import br.com.loja.checkout.cupom.Cupom;
4	import br.com.loja.checkout.entrega.ModalidadeEntrega;
5	import java.math.BigDecimal;
6	import java.util.Arrays;
7	import java.util.List;
8	import java.util.Map;
9	import java.util.Objects;
10	import java.util.Optional;
11	import java.util.function.Function;
12	import java.util.stream.Collectors;
13	import org.springframework.stereotype.Service;
14	
15	@Service
16	public class CheckoutService {
17	
18	    private final Map<String, ModalidadeEntrega> modalidades;
19	    private final Map<String, Cupom> cupons;
20	
21	    public CheckoutService(List<ModalidadeEntrega> modalidades, List<Cupom> cupons) {
22	        this.modalidades = modalidades.stream().collect(Collectors.toMap(ModalidadeEntrega::codigo, Function.identity()));
23	        this.cupons = cupons.stream().collect(Collectors.toMap(Cupom::codigo, Function.identity()));
24	    }
25	
26	    public ResumoCompra resumir(CheckoutRequest request) {
27	        Carrinho carrinho = carrinhoValido(request.itens());
28	        NivelClube nivel = buscar(NivelClube.class, request.nivelClube())
29	                .orElseThrow(() -> new CheckoutException("NIVEL_CLUBE_INVALIDO"));
30	        Regiao regiao = buscar(Regiao.class, request.regiao())
31	                .orElseThrow(() -> new CheckoutException("REGIAO_INVALIDA"));
32	        ModalidadeEntrega modalidade = modalidadeValida(request.modalidadeEntrega(), carrinho);
33	        Optional<Cupom> cupom = cupomValido(request.cupom(), carrinho);
34	        FormaPagamento forma = buscar(FormaPagamento.class, request.formaPagamento())
35	                .orElseThrow(() -> new CheckoutException("FORMA_PAGAMENTO_INVALIDA"));
36	        int parcelas = Objects.requireNonNullElse(request.parcelas(), 1);
37	        if (!forma.aceitaParcelas(parcelas)) {
38	            throw new CheckoutException("PARCELAMENTO_INVALIDO");
39	        }
40	
41	        BigDecimal subtotal = carrinho.subtotal();
42	        BigDecimal frete = nivel.isentaFrete() ? Dinheiro.centavos(BigDecimal.ZERO) : modalidade.frete(carrinho);
43	        BigDecimal desconto = cupom.map(c -> c.desconto(carrinho, frete)).orElse(Dinheiro.centavos(BigDecimal.ZERO));
44	        BigDecimal seguro = regiao.seguro(subtotal);
45	        BigDecimal totalPedido = subtotal.subtract(desconto).add(frete).add(seguro);
46	
47	        if (!forma.atende(totalPedido)) {
48	            throw new CheckoutException("FORMA_PAGAMENTO_INDISPONIVEL");
49	        }
50	        Pagamento pagamento = forma.pagar(totalPedido, parcelas);
51	
52	        return new ResumoCompra(
53	                subtotal,
54	                desconto,
55	                frete,
56	                modalidade.prazoDias(),
57	                seguro,
58	                pagamento.totalFinal().subtract(totalPedido),
59	                pagamento.totalFinal(),
60	                parcelas,
61	                pagamento.valorParcela(),
62	                nivel.credito(subtotal),
63	                nivel.brinde(subtotal));
64	    }
65	
66	    private static Carrinho carrinhoValido(List<Item> itens) {
67	        if (itens == null || itens.isEmpty() || itens.stream().anyMatch(item -> item == null || !item.valido())) {
68	            throw new CheckoutException("PEDIDO_INVALIDO");
69	        }
70	        return new Carrinho(itens);
71	    }
72	
73	    private ModalidadeEntrega modalidadeValida(String codigo, Carrinho carrinho) {
74	        ModalidadeEntrega modalidade = Optional.ofNullable(codigo).map(modalidades::get)
75	                .orElseThrow(() -> new CheckoutException("MODALIDADE_INVALIDA"));
76	        if (!modalidade.atende(carrinho)) {
77	            throw new CheckoutException("MODALIDADE_INDISPONIVEL");
78	        }
79	        return modalidade;
80	    }
81	
82	    private Optional<Cupom> cupomValido(String codigo, Carrinho carrinho) {
83	        if (codigo == null) {
84	            return Optional.empty();
85	        }
86	        Cupom cupom = Optional.ofNullable(cupons.get(codigo))
87	                .orElseThrow(() -> new CheckoutException("CUPOM_INVALIDO"));
88	        if (!cupom.aplicavel(carrinho)) {
89	            throw new CheckoutException("CUPOM_NAO_APLICAVEL");
90	        }
91	        return Optional.of(cupom);
92	    }
93	
94	    private static <E extends Enum<E>> Optional<E> buscar(Class<E> tipo, String codigo) {
95	        return Arrays.stream(tipo.getEnumConstants()).filter(e -> e.name().equals(codigo)).findFirst();
96	    }
97	}
