1	package br.com.loja.checkout;
2	
3	import java.math.BigDecimal;
4	import java.math.MathContext;
5	import java.math.RoundingMode;
6	
7	public enum FormaPagamento {
8	
9	    PIX {
10	        @Override
11	        public boolean aceitaParcelas(int parcelas) {
12	            return parcelas == 1;
13	        }
14	
15	        @Override
16	        public Pagamento pagar(BigDecimal totalPedido, int parcelas) {
17	            BigDecimal totalFinal = totalPedido.subtract(Dinheiro.percentual(totalPedido, "5"));
18	            return new Pagamento(totalFinal, totalFinal);
19	        }
20	    },
21	
22	    BOLETO {
23	        private static final BigDecimal TARIFA = new BigDecimal("3.49");
24	        private static final BigDecimal LIMITE = new BigDecimal("1000.00");
25	
26	        @Override
27	        public boolean aceitaParcelas(int parcelas) {
28	            return parcelas == 1;
29	        }
30	
31	        @Override
32	        public boolean atende(BigDecimal totalPedido) {
33	            return totalPedido.compareTo(LIMITE) <= 0;
34	        }
35	
36	        @Override
37	        public Pagamento pagar(BigDecimal totalPedido, int parcelas) {
38	            BigDecimal totalFinal = totalPedido.add(TARIFA);
39	            return new Pagamento(totalFinal, totalFinal);
40	        }
41	    },
42	
43	    CARTAO {
44	        private static final int MAXIMO_SEM_JUROS = 3;
45	        private static final int MAXIMO_PARCELAS = 12;
46	        private static final BigDecimal TAXA_MENSAL = new BigDecimal("0.0199");
47	
48	        @Override
49	        public boolean aceitaParcelas(int parcelas) {
50	            return parcelas >= 1 && parcelas <= MAXIMO_PARCELAS;
51	        }
52	
53	        @Override
54	        public Pagamento pagar(BigDecimal totalPedido, int parcelas) {
55	            if (parcelas <= MAXIMO_SEM_JUROS) {
56	                return new Pagamento(totalPedido,
57	                        totalPedido.divide(BigDecimal.valueOf(parcelas), 2, RoundingMode.HALF_EVEN));
58	            }
59	            BigDecimal parcela = Dinheiro.centavos(parcelaPrice(totalPedido, parcelas));
60	            return new Pagamento(parcela.multiply(BigDecimal.valueOf(parcelas)), parcela);
61	        }
62	
63	        /** Tabela Price: total × taxa ÷ (1 − (1 + taxa)^−n). */
64	        private BigDecimal parcelaPrice(BigDecimal totalPedido, int parcelas) {
65	            MathContext mc = MathContext.DECIMAL128;
66	            BigDecimal descontoComposto = BigDecimal.ONE.divide(BigDecimal.ONE.add(TAXA_MENSAL).pow(parcelas, mc), mc);
67	            return totalPedido.multiply(TAXA_MENSAL).divide(BigDecimal.ONE.subtract(descontoComposto), mc);
68	        }
69	    };
70	
71	    public abstract boolean aceitaParcelas(int parcelas);
72	
73	    public boolean atende(BigDecimal totalPedido) {
74	        return true;
75	    }
76	
77	    public abstract Pagamento pagar(BigDecimal totalPedido, int parcelas);
78	}
