1	package br.com.loja.checkout;
2	
3	import java.math.BigDecimal;
4	import java.math.RoundingMode;
5	
6	/** Arredondamento de valores em dinheiro: centavos, meio para o par. */
7	public final class Dinheiro {
8	
9	    private static final BigDecimal CEM = BigDecimal.valueOf(100);
10	
11	    private Dinheiro() {
12	    }
13	
14	    public static BigDecimal centavos(BigDecimal valor) {
15	        return valor.setScale(2, RoundingMode.HALF_EVEN);
16	    }
17	
18	    public static BigDecimal centavos(String valor) {
19	        return centavos(new BigDecimal(valor));
20	    }
21	
22	    /** {@code percentual}% de {@code valor}, arredondado para centavos. */
23	    public static BigDecimal percentual(BigDecimal valor, String percentual) {
24	        return centavos(valor.multiply(new BigDecimal(percentual)).divide(CEM));
25	    }
26	}
